function sqrtCeil(x) {
  let lo = 0, hi = x;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (mid * mid >= x) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

